snippet_css:
:root{
  --bg: #FFFDF5;
  --fg: #000000;
  --muted: #3B3B3B;
  --surface: #FFFFFF;
  --border: #000000;
  --accent: #2F5BFF;
  --accent-fg: #FFFFFF;
  --radius: 0px;
  --radius-sm: 0px;
  --shadow: 6px 6px 0 #000000;
  --btn-shadow: 5px 5px 0 #000000;
  --art-bg: linear-gradient(135deg,#FFE600 0 34%,#A388EE 34% 67%,#4ECDC4 67%);
  --media-bg: radial-gradient(#000 2px,transparent 2.5px) 0 0/16px 16px,#FFE600;
  --cta-bg: #FFE600;
  --input-bg: #FFFFFF;
  --ok: #008751;
  --warn: #D6002A;
  --font-display: 'Archivo Black','Noto Sans TC',sans-serif;
  --font-body: 'Space Grotesk','Noto Sans TC',sans-serif;
  --font-mono: 'Space Grotesk',ui-monospace,monospace;
  --focus-ring: var(--accent);
}

snippet_tailwind:
